public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Check if the starting and ending coordinates are valid
  if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
    return "cannot be travelled";
  }

  // Check if the starting and ending coordinates are the same
  if (start[0] == end[0] && start[1] == end[1]) {
    return "can be travelled";
  }

  // Check if the paths between adjacent n-tersections are valid
  for (int[] path : paths) {
    if (path[0] >= n || path[0] < 0 || path[1] >= n || path[1] < 0) {
      return "cannot be travelled";
    }
  }

  // Check if there is a path between the starting and ending n-tersections
  boolean foundPath = false;
  for (int[] path : paths) {
    if (path[0] == start[0] && path[1] == start[1] || path[0] == end[0] && path[1] == end[1]) {
      foundPath = true;
      break;
    }
  }

  if (foundPath) {
    return "can be travelled";
  } else {
    return "cannot be travelled";
  }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a boolean array to keep track of visited n-tersections
  boolean[] visited = new boolean[n];

  // Initialize a queue to store the n-tersections to be visited
  Queue<int[]> queue = new LinkedList<>();

  // Mark the starting n-tersection as visited and enqueue it
  visited[start[0]][start[1]] = true;
  queue.add(start);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Dequeue the current n-tersection
    int[] current = queue.remove();

    // Check if the current n-tersection is the ending n-tersection
    if (current[0] == end[0] && current[1] == end[1]) {
      return "can be travelled";
    }

    // Loop through the paths adjacent to the current n-tersection
    for (int i = 0; i < paths.length; i++) {
      // If the current n-tersection is not the starting n-tersection, check if it is not visited yet
      if (current[0] != start[0] || current[1] != start[1]) {
        // If it is not visited yet, mark it as visited and enqueue it
        if (!visited[paths[i][0]][paths[i][1]]) {
          visited[paths[i][0]][paths[i][1]] = true;
          queue.add(paths[i]);
        }
      }
    }
  }

  // If we reach here, it means we could not find a path from start to end
  return "cannot be travelled";
}

