  minCost1 = cost[0];
  minCost2 = cost[1];

  // Loop through the rest of the steps
  for (int i = 2; i < cost.length; i++) {
    // Calculate the minimum cost of the next step
    minCost = Math.min(minCost1 + cost[i], minCost2 + cost[i]);

    // Shift the minimum cost to the previous step
    minCost2 = minCost1;
    minCost1 = minCost;
  }

  // Return the minimum cost of the top step
  return minCost;
