public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int row1 = i;
                while (row1 < m && mat[row1][j] == 1) {
                    row1++;
                }
                row1--;

                int col1 = j;
                while (col1 < n && mat[i][col1] == 1) {
                    col1++;
                }
                col1--;

                int row2 = i;
                while (row2 >= 0 && mat[row2][j] == 1) {
                    row2--;
                }
                row2++;

                int col2 = j;
                while (col2 >= 0 && mat[i][col2] == 1) {
                    col2--;
                }
                col2++;

                int len = Math.max(row1 - row2 + 1, col1 - col2 + 1);
                longest = Math.max(longest, len);
            }
        }
    }

    return longest;
}

