public static int squarePermutations(int[] A) {
    int[][] dp = new int[A.length][A.length];

    for (int i = 0; i < A.length; i++) {
        for (int j = 0; j <= i; j++) {
            if (i == j) {
                dp[i][j] = 1;
            } else {
                int sum = A[i] + A[j];
                int root = (int)Math.sqrt(sum);
                if (root * root == sum) {
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
                } else {
                    dp[i][j] = dp[i - 1][j - 1];
                }
            }
        }
    }

    return dp[A.length - 1][A.length - 1];
}

